-- 206_aims_ia_concepts.sql  |  AIMS-IA - 158 concepts + task_concepts links
--
-- Split out of 205 deliberately. A wrong task row fails loudly; a concept
-- description more specific than the standard passes every gate, and the item
-- generator then writes the defect faithfully. That is what migration 198 had to
-- repair on ISMS-IA: four rows asserted things ISO 19011 does not say, and the
-- model was right to obey them.
--
-- Every description below was written against the two standards held in the
-- project - ISO/IEC 42001:2023 and ISO 19011:2026 - reading the clause text, not
-- from recall. No description cites a clause of ISO/IEC 22989, ISO/IEC 42006 or
-- ISO/IEC 17021-1, none of which the body holds.
--
-- Slugs and their task assignment are generated from AIMS-IA_JTA_v1_1.md
-- (v1.1-LOCKED) and were reconciled against it: 158 of 158, same order, no drift.
--
-- Run in the Supabase SQL editor. One transaction.
-- ============================================================================

begin;

insert into public.concepts (certification_id, slug, name, description) values
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-audit-party-types', 'First-, second- and third-party audits',
   'ISO 19011:2026 Table 1 separates audits by who requests and who conducts them. First party is the internal audit an organization performs on itself. Second party is an audit of an external provider, or an audit of the organization by an external interested party. Third party covers certification audit, accreditation assessment, and statutory or regulatory audit. The document states in its introduction that it concentrates on first and second party, and that ISO/IEC 17021-1 provides the requirements for auditing management systems for third-party certification.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-internal-audit-definition', 'Internal audit',
   'ISO 19011:2026 clause 3.1 defines an audit as a systematic, independent and documented process for obtaining objective evidence and evaluating it objectively to determine the extent to which the audit criteria are fulfilled. Note 2 to entry adds that an internal audit is conducted by, or on behalf of, the organization itself. An organization may therefore engage a contracted auditor and the audit remains a first-party audit; what makes it internal is whose management system is being examined, not who holds the pen.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-audit-client-vs-auditee', 'Audit client and auditee',
   'ISO 19011:2026 clause 3.13 defines the audit client as the organization or person requesting the audit, and clause 3.14 defines the auditee as the organization or the parts of it being audited. A note to 3.13 records that in an internal audit the audit client can also be the auditee, or the individual managing the audit programme. The roles stay distinct even when one organization fills all of them, and identifying who requested the audit is how the auditor knows to whom the report is owed.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-seven-principles', 'The seven principles of auditing',
   'ISO 19011:2026 clause 4 sets out seven principles: integrity (4.2), fair presentation (4.3), due professional care (4.4), confidentiality (4.5), independence (4.6), evidence-based approach (4.7) and risk-based approach (4.8). Clause 4.1 states that adherence to them is fundamental to audit conclusions that are relevant and sufficient, and that it enables auditors working independently of one another to reach similar conclusions in similar circumstances. Each principle is expressed as a should.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-principles-carry-no-precedence', 'The principles are not ranked',
   'ISO 19011:2026 presents the seven principles without ranking them. Clause 4.1 says only that adherence to them is fundamental and that the guidance in Clauses 5 to 7 is based on the seven outlined in 4.2 to 4.8. It says nothing about precedence in either direction; the words precedence, hierarchy and rank do not appear in the document. Where two principles engage a situation differently, nothing in the text decides between them and the auditor weighs them. The absence of a ranking rule is an observation about the text, not a stated rule of no ranking.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-principle-interaction-in-practice', 'Principles in tension',
   'A single audit situation can engage several principles at once. The auditor first determines which are actually engaged, since not every principle bears on every situation, and then reasons to a defensible resolution. The pairs that genuinely collide are drawn from the clause text: evidence-based (4.7, verifiability and sampling) against risk-based (4.8, which should substantively influence planning and implementation); independence (4.6) against due professional care (4.4); integrity (4.2) against fair presentation (4.3); and fair presentation (4.3, completeness) against confidentiality (4.5, discretion).'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-professional-judgement', 'Professional judgement in auditing',
   'ISO 19011:2026 clause 4.4 describes due professional care as the application of diligence and judgement in auditing, and names the ability to make reasoned judgements in all audit situations as an important factor in exercising it. Because the document offers guidance rather than requirements, and because it ranks no principle above another, the resolution of a genuine tension is the auditor''s reasoned judgement rather than a rule the auditor can cite. Annex A.3 gives further guidance on professional judgement.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-method-vs-criteria', 'Audit methodology and audit criteria are different documents',
   'ISO 19011:2026 supplies the method: how to manage an audit programme, conduct an audit and evaluate auditor competence. ISO/IEC 42001:2023 supplies the criteria: the requirements an AI management system is examined against. A finding is raised against criteria, never against the method. Confusing the two produces a finding that cannot stand, because a guidance document contains no requirement capable of being unfulfilled.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-19011-is-guidance-only', 'ISO 19011 states no requirements',
   'ISO 19011:2026 clause 1 states that the document gives guidance on auditing management systems. It contains 264 instances of should and one of shall, which is boilerplate about ISO patent rights and not an audit requirement. Clause 2 records that there are no normative references in the document. An auditor may therefore write that ISO 19011 recommends, advises or calls for something, and may quote a clause and its modal, but never that ISO 19011 requires or mandates anything.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-no-certification-to-19011', 'No organization is certified to ISO 19011',
   'Because ISO 19011:2026 states no requirements, there is nothing for an organization to conform to and nothing to certify against. It is written for auditors and audit programme managers rather than for the organizations they audit. A claim that an audit programme is compliant with, or certified to, ISO 19011 misdescribes what the document is.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-audit-criteria-definition', 'Audit criteria',
   'ISO 19011:2026 clause 3.8 defines audit criteria as the set of requirements used as a reference against which objective evidence is compared. A note records that requirements may include policies, procedures, work instructions, legal requirements and contractual obligations, and a further note that where the criteria are legal requirements the words compliance and non-compliance are often used in a finding. For this credential the criteria are ISO/IEC 42001:2023 together with the organization''s own AI management system requirements, as clause 9.2.1 of that standard sets out.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-independence-wherever-practicable', 'Independence wherever practicable',
   'ISO 19011:2026 clause 4.6 states that auditors should be independent of the activity being audited wherever practicable, and should in all cases act in a manner free from bias and conflict of interest. It adds that when it is not possible for internal auditors to be independent of the activity being audited, every effort should be made to remove bias and encourage objectivity. The principle is therefore conditional by its own wording, and neither ISO 19011 nor ISO/IEC 42001 forbids auditing work one has contributed to.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-objectivity-safeguards', 'Safeguards for objectivity',
   'Where independence from the audited activity is not practicable, objectivity is preserved by declared and visible measures rather than by assertion: disclosing the auditor''s involvement to the audit client, having a second auditor review the evidence and findings in the affected area, restricting the auditor to evidence others can verify, or assigning that part of the scope to a different member of the audit team. ISO 19011:2026 clause 4.6 asks that findings and conclusions rest only on the audit evidence, which is the test a safeguard has to meet.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-small-organization-constraint', 'Auditing in a small organization',
   'In a small organization the only person competent to evaluate an AI system is often the person who built or operates it. ISO 19011:2026 anticipates this in clause 4.6 by carving out the case where internal auditors cannot be independent of the activity audited. The response is to name the constraint in the audit plan and record the safeguards applied, not to omit the area from scope or to present the audit as more independent than it was.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-42001-impartiality-clause', 'What ISO/IEC 42001 asks about auditor selection',
   'ISO/IEC 42001:2023 clause 9.2.2 b) states that the organization shall select auditors and conduct audits to ensure objectivity and the impartiality of the audit process. That is the whole of the standard''s requirement on the point: it names no independence rule, no separation of duties and no prohibition on auditing one''s own area. The detail of how objectivity is achieved is left to the organization, and ISO 19011 clause 4.6 is where the guidance sits.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-internal-vs-certification-audit', 'Internal audit and certification audit',
   'An internal audit under ISO/IEC 42001:2023 clause 9.2 provides the organization with information on whether its AI management system conforms to its own requirements and to the standard, and is effectively implemented and maintained. A certification audit is conducted by an external body to decide whether to grant a certificate. They differ in who requests them, who reports to whom, and what follows: an internal audit produces findings for the organization to act on, and no certificate.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-17021-1-governs-certification-bodies', 'Where third-party certification requirements live',
   'ISO 19011:2026 states in its introduction that ISO/IEC 17021-1 provides the requirements for auditing management systems for third-party certification, and that ISO 19011 can offer useful additional guidance alongside it. ISO/IEC 17021-1 governs the certification body, not the organization being audited and not its internal auditors. Concepts an internal auditor may meet from that world, such as a major and minor grading of nonconformities, originate there rather than in ISO/IEC 42001.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-42006-scope-boundary', 'ISO/IEC 42006 and the AI certification body',
   'ISO/IEC 42006:2025 specifies additional requirements to ISO/IEC 17021-1 for bodies that audit and certify an AI management system against ISO/IEC 42001. It addresses the competence of certification body personnel, audit time and certification documents, and can be used as accreditation criteria. It applies to the certification body and has no application to a first-party audit, which is why an internal auditor works from ISO/IEC 42001 and ISO 19011 alone.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-no-certification-decision', 'The internal auditor makes no certification decision',
   'An internal auditor reports findings and conclusions to the organization''s management. The auditor does not grant, refuse, suspend or withdraw a certificate, does not determine audit time for a certification cycle, and does not decide whether an organization is fit to be certified. Those are certification body activities. An internal audit report that reads as a certification recommendation has stepped outside the remit of ISO/IEC 42001 clause 9.2.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-programme-objectives', 'Audit programme objectives',
   'ISO 19011:2026 clause 5.2 states that the audit client should ensure audit programme objectives are established to direct the planning and conducting of audits, and that those objectives should be consistent with the audit client''s strategic direction and context and support its management system policies and objectives. The clause lists what they can be based on, including the needs and expectations of interested parties, management system requirements, the auditee''s level of performance, and the need to evaluate organizations in the supply chain.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-objectives-from-context', 'Programme objectives follow from context',
   'Audit programme objectives are not generic. ISO 19011:2026 clause 5.2 ties them to the audit client''s strategic direction and context, which for an AI management system means the AI systems in use, the roles the organization holds toward them, and the interested parties affected. A programme whose objectives could be pasted into any organization has not been derived from context and cannot direct the planning of audits in the way the clause describes.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-programme-vs-individual-audit', 'Programme objectives and audit objectives',
   'ISO 19011:2026 distinguishes the objectives of the audit programme (clause 5.2) from the objectives of an individual audit (clause 5.5.2), and states that the latter should be consistent with the former. The programme spans a set of audits over a time frame and directs where audit effort goes; an individual audit defines what that one audit is to accomplish. Conflating them produces a programme that is a schedule rather than a design.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-programme-risks', 'Risks and opportunities to the audit programme',
   'ISO 19011:2026 clause 5.3 records that risks and opportunities related to the auditee''s context can affect the achievement of the audit programme''s objectives, and that the individual managing the programme should identify them and present them to the audit client when developing the programme and its resource requirements. The clause lists risk sources including planning, resources, selection of the audit team, communication, implementation, records and their control, and monitoring and review. These are risks to the audit, not the auditee''s own risks.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-risk-based-approach', 'The risk-based approach to auditing',
   'ISO 19011:2026 clause 4.8 describes the risk-based approach as one that considers risks and opportunities, and states that it should substantively influence the planning and implementation of the audit programme and the planning, conducting and reporting of audits, so that audits focus on matters significant for the audit client and for achieving the programme objectives. It is expressed as a should, like every principle in clause 4, and it directs where effort concentrates rather than authorising an area to go unexamined.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-programme-resources', 'Audit programme resources',
   'ISO 19011:2026 clause 5.4.4 covers the resources an audit programme needs, and clause 5.3 names insufficient time, equipment, training and competent auditors among the risks to the programme. Resourcing is where the risk-based approach becomes visible: concentrating auditor days on higher-risk processes necessarily thins coverage elsewhere, and the programme should record that choice rather than leave it implicit.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-risk-vs-evidence-tension', 'Risk-based focus against evidence sufficiency',
   'The risk-based approach (4.8) directs effort toward significant matters; the evidence-based approach (4.7) requires that conclusions rest on verifiable evidence drawn from an appropriate sample. Concentrating hours on a high-risk AI system can leave another area sampled too thinly to support any conclusion about it. Nothing in ISO 19011 ranks the two, so the auditor resolves it by judgement and by stating plainly what the audit did and did not cover.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-auditor-competence', 'Auditor competence',
   'ISO 19011:2026 clause 7.2 covers determining auditor competence, distinguishing personal behaviour (7.2.2) from knowledge and skills (7.2.3). Clause 5.4.2 addresses the competence of the individual managing the audit programme, and 5.5.4 the selection of audit team members. Clause 7.3 adds that evaluation criteria should be both qualitative and quantitative. All of it is guidance; the organization determines what competence its own programme requires.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-aims-specific-knowledge', 'Knowledge specific to auditing an AI management system',
   'Auditing an AI management system calls for knowledge a general management-system auditor may not hold: what an AI system is and what its life cycle stages are, what data provenance and data quality documentation look like, how an impact assessment differs from a risk assessment, and what evidence a tooling or computing resource control produces. The gap is usually in reading the evidence rather than in audit technique.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-technical-expert-vs-auditor', 'Technical expert on the audit team',
   'ISO 19011:2026 clause 3.15 defines the audit team as one or more persons conducting an audit, supported if needed by technical experts, and clause 3.17 defines a technical expert as a person who provides specific knowledge or expertise to the audit team. A technical expert supplies subject-matter understanding and does not act as an auditor. Bringing a data scientist onto the team to interpret model evaluation evidence is the intended use; having that person audit their own team''s work is not.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-competence-gap-remedies', 'Closing a competence gap',
   'Where the audit team lacks the competence an AI system demands, the available responses are to add a technical expert, to train or pair the auditor, to narrow the audit scope and say so, or to reschedule until competence is available. What is not available is proceeding and writing conclusions the evidence was never understood well enough to support, since ISO 19011:2026 clause 4.2 b) asks auditors to undertake auditing activities only if they are competent to do so.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-organizational-roles-4-1', 'Determining the organization''s roles',
   'ISO/IEC 42001:2023 clause 4.1 requires the organization to determine external and internal issues relevant to its purpose, to consider the intended purpose of the AI systems it develops, provides or uses, and to determine its roles with respect to those systems. This is a requirement of the standard and the determination is auditable: the auditor looks for the systems named, the roles assigned and the reasoning recorded.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-developer-provider-user', 'Developer, provider and user',
   'ISO/IEC 42001:2023 frames an organization''s relationship to an AI system in terms of developing, providing or using it. The obligations that follow differ: an organization that develops a system holds life-cycle and data responsibilities that a pure user does not, while a user carries responsibilities for intended use and human oversight that a developer selling onward may not. The role determination under clause 4.1 is what makes those differences concrete for a given system.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-multiple-roles-one-system', 'More than one role on a single system',
   'An organization can hold several roles toward the same AI system at once. Fine-tuning a third-party model and then offering it to customers makes the organization both a user of the base model and a provider of the derived one. Nothing in ISO/IEC 42001:2023 clause 4.1 restricts an organization to a single role, and an AIMS that assigns one role per system without examining whether more apply has narrowed its own scope by assumption.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-scope-follows-roles', 'Scope follows from the role determination',
   'ISO/IEC 42001:2023 clause 4.3 requires the organization to determine the boundaries and applicability of the AI management system to establish its scope, considering the issues in 4.1 and the requirements in 4.2. Because 4.1 includes the determination of roles, the scope is downstream of that determination. An auditor testing scope therefore tests the role determination first: a scope that excludes an activity the organization performs in a role it holds is an exclusion that needs justification.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-role-changes-obligations', 'A change of role changes what applies',
   'Because obligations attach to roles, a change in role is a change in what the AIMS must cover. An organization that begins offering an internally used system to customers has become a provider; one that starts fine-tuning a model it previously only consumed has taken on development activity. ISO/IEC 42001:2023 clause 6.3 addresses planning of changes, and an audit programme covering an evolving AI estate should expect the role determination to be revisited rather than treated as settled.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-individual-audit-objectives', 'Objectives for an individual audit',
   'ISO 19011:2026 clause 5.5.2 states that each individual audit should be based on defined audit objectives, scope and criteria, consistent with the overall programme objectives. It lists what the objectives can include: determining the extent of conformity to the criteria, evaluating the management system''s capability to meet statutory, regulatory and other requirements, evaluating its effectiveness in meeting intended results, and finding opportunities for improvement.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-audit-scope-definition', 'Audit scope',
   'ISO 19011:2026 clause 3.6 defines audit scope as the extent and boundaries of an audit, with a note that it generally includes a description of the physical and virtual locations, functions, organizational units, activities and processes, and the time period covered. For an AI management system audit the virtual locations and the specific AI systems in scope matter as much as the organizational units, and a scope that names neither cannot later be tested against a finding.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-criteria-selection', 'Selecting the audit criteria',
   'The criteria for an AIMS internal audit come from ISO/IEC 42001:2023 clause 9.2.1, which asks whether the management system conforms to the organization''s own requirements for it and to the requirements of the standard, and whether it is effectively implemented and maintained. Both limbs are criteria: an audit that tests only the standard and not the organization''s own AIMS requirements has audited half of what clause 9.2.1 names.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-42001-9-2-2-a', 'What the standard requires of each audit',
   'ISO/IEC 42001:2023 clause 9.2.2 states that the organization shall plan, establish, implement and maintain an audit programme including frequency, methods, responsibilities, planning requirements and reporting; that when establishing it the organization shall consider the importance of the processes concerned and the results of previous audits; and that the organization shall define the audit objectives, criteria and scope for each audit, select auditors and conduct audits so as to ensure objectivity and impartiality, and ensure results are reported to relevant managers. Documented information shall be available as evidence of the programme''s implementation and of the audit results.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-auditing-methods', 'Selecting auditing methods',
   'ISO 19011:2026 clause 5.5.3 states that the individual managing the audit programme should select and determine the methods for conducting an audit effectively and efficiently, depending on the defined objectives, scope and criteria, and that audits can be performed on-site, remotely or as a combination, suitably balanced with consideration of associated risks and opportunities. Annex A.1 gives further guidance on applying auditing methods.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-remote-audit-methods', 'Remote auditing methods',
   'ISO 19011:2026 Annex A.16 addresses remote auditing methods: an audit using technology during the audit process for observing, interviewing and verifying objective evidence. It records that remote methods can be necessary for auditing virtual locations, that ensuring the audit is effectively conducted is a joint responsibility of auditee and auditors, and that remote methods can introduce additional risks and opportunities. The fourth edition expanded this guidance from ISO/IEC TS 17012.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-virtual-location', 'Virtual locations',
   'ISO 19011:2026 describes a virtual location as one where an organization performs work or provides a service using an online environment, enabling individuals to execute processes irrespective of physical location. Much of an AI management system''s evidence lives in exactly such places: model registries, pipelines, cloud environments and logging platforms. Clause 3.6 notes that audit scope generally includes a description of virtual as well as physical locations.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-method-fit-to-evidence', 'Matching method to evidence',
   'The choice between on-site and remote is a question of what the evidence is and where it lives, not of rigour or convenience. A model registry or an event log is examined the same way from any location; an operating environment, a physical control room or the behaviour of a team may not be. ISO 19011:2026 clause 5.5.3 asks that the balance of methods be based on consideration of associated risks and opportunities, which is a judgement to record rather than a default to apply.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-programme-monitoring', 'Monitoring the audit programme',
   'ISO 19011:2026 clause 5.6 covers monitoring the audit programme, and clause 5.5.6 the managing of audit programme results. Monitoring asks whether the programme is being implemented as planned and whether it is achieving its objectives, which is a different question from whether any individual audit was conducted well.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-programme-review-improvement', 'Reviewing and improving the programme',
   'ISO 19011:2026 clause 5.7 addresses reviewing and improving the audit programme. A review considers whether the programme''s objectives remain appropriate, what the results across audits show, whether resourcing and competence were adequate, and what should change. The programme is itself subject to improvement, and treating it as fixed is a common weakness an internal auditor can raise about their own function.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-audit-records', 'Audit programme records',
   'ISO 19011:2026 clause 5.5.7 addresses managing audit related records. ISO/IEC 42001:2023 clause 9.2.2 separately requires that documented information shall be available as evidence of the implementation of the audit programme and of the audit results. The standard''s requirement is the one a nonconformity can be raised against; the ISO 19011 guidance describes what good record management looks like.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-audit-sequence', 'The sequence of audit activities',
   'ISO 19011:2026 clause 6 sets out the activities of an individual audit in order: initiating the audit (6.2), preparing auditing activities (6.3), conducting auditing activities (6.4), preparing and distributing the audit report (6.5), completing the audit (6.6) and conducting the audit follow-up (6.7). The sequence is guidance, and clause 6.1 notes it can be adapted; what it is not is a checklist that substitutes for judgement about what a particular audit needs.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-initiating-the-audit', 'Initiating the audit',
   'ISO 19011:2026 clause 6.2 covers initiating the audit: establishing contact with the auditee (6.2.2) and determining the feasibility of the audit (6.2.3). Establishing contact confirms authority for the audit, provides information on objectives, scope, methods and team composition, and arranges access. It is where the audit''s terms are agreed rather than assumed.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-audit-feasibility', 'Audit feasibility',
   'ISO 19011:2026 clause 6.2.3 addresses determining whether the audit can be conducted at all: whether sufficient and appropriate information is available for planning, whether the auditee will cooperate, and whether adequate time and resources exist. A feasibility problem raised at initiation is a scheduling matter; the same problem discovered during fieldwork has already consumed the audit''s time and the auditee''s.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-completing-the-audit', 'Completing the audit',
   'ISO 19011:2026 clause 6.6 covers completing the audit, which occurs when the planned activities have been carried out and the report distributed. Clause 6.7 then addresses audit follow-up, which may extend past completion. Documents are retained or disposed of by agreement, and lessons for the audit programme are fed back under clause 5.7.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-documented-information-review', 'Reviewing documented information',
   'ISO 19011:2026 clause 6.3.1 covers performing the review of documented information before fieldwork: understanding the management system, gathering information to prepare audit activities and working documents, and forming a view of the extent of documentation relative to the audit objectives, scope and criteria. If what is supplied is inadequate the audit team leader should inform those responsible, and decide whether to continue or to suspend until the matter is resolved.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-audit-planning', 'Audit planning',
   'ISO 19011:2026 clause 6.3.2 covers audit planning: the plan describes the activities and arrangements for the audit and provides the basis for agreement among the audit client, audit team and auditee. Its detail should reflect the scope, complexity and the risks and opportunities of the audit. For an AIMS audit the plan is where the specific AI systems, virtual locations and evidence sources are named.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-plan-adjustment', 'Adjusting the plan during the audit',
   'ISO 19011:2026 clause 6.4.7 records that where the audit team becomes aware of new or changed circumstances, or of risks or opportunities, these should be addressed accordingly. A plan is a design, not a commitment to ignore what the evidence shows. Changes are agreed with the audit client and auditee and recorded, so that the report describes the audit that was actually conducted.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-working-documents', 'Audit working documents',
   'ISO 19011:2026 clause 6.3.4 covers preparing documented information for the audit, and Annex A.13 gives guidance on working documents such as checklists, sampling plans and forms for recording evidence and findings. Annex A.13 also cautions that working documents should not restrict the audit activities, which can change as a result of information collected during the audit.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-sampling-general', 'Audit sampling',
   'ISO 19011:2026 Annex A.6.1 describes sampling as what takes place when it is not practical or cost-effective to examine all available information, and defines it as selecting less than one hundred per cent of the population to obtain and evaluate evidence about some characteristic of that population in order to form a conclusion about it. It states the associated risk plainly: the sample is not necessarily representative, so the auditor''s conclusion can differ from the one the whole population would have produced.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-judgement-based-sampling', 'Judgement-based sampling',
   'ISO 19011:2026 Annex A.6.2 covers sampling that relies on the auditor''s knowledge and experience to select what to examine, targeting items by risk, materiality, complexity or previous findings. It is efficient and it does not support a statistical statement about the population. The auditor who samples this way can say what the examined items showed; they cannot report a rate.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-statistical-sampling', 'Statistical sampling',
   'ISO 19011:2026 Annex A.6.3 covers sampling designed so that conclusions about the population can be drawn with a stated confidence, which requires a sampling design based on probability theory. It costs more to set up and it supports inference that judgement-based sampling does not. The choice between the two follows from what the audit needs to conclude.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-sample-defensibility', 'What a sample can support',
   'A finding rests on the sample that produced it. If ten of a thousand model cards were examined and three lacked required content, the defensible statement concerns those three and what they indicate; a claim about the other nine hundred and ninety requires a sampling design that supports it. ISO 19011:2026 Annex A.6.1 names non-representativeness as the inherent sampling risk, which is why the sample and its basis belong in the audit record.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-collecting-verifying-information', 'Collecting and verifying information',
   'ISO 19011:2026 clause 6.4.7 states that information relevant to the audit objectives, scope and criteria should be collected by appropriate sampling and should be verified as far as practicable, and that only information which can be subject to some degree of verification should be accepted as audit evidence. Where the degree of verification is low, the auditor should use professional judgement to determine how much reliance to place on it. Evidence leading to findings should be recorded.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-evidence-vs-assertion', 'Evidence and assertion',
   'A description of a process is not evidence that the process operates. ISO 19011:2026 clause 3.10 defines audit evidence as records, statements of fact or other information relevant to the audit criteria and verifiable. A statement of fact from an interviewee can be audit evidence; an opinion, an intention or an assurance is not, and the auditor''s confidence in the speaker does not convert one into the other.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-verifying-information', 'Testing information for sufficiency',
   'ISO 19011:2026 Annex A.5 asks the auditor to consider, so far as practicable, whether information provides sufficient objective evidence that requirements are being met: whether it is complete, meaning all expected content is present; correct, meaning it conforms to other reliable sources; consistent, in itself and with related documented information; and current. It adds that where information arrives in a manner other than expected, the integrity of the audit evidence should be assessed.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-evidence-based-approach', 'The evidence-based approach',
   'ISO 19011:2026 clause 4.7 describes the evidence-based approach as the rational method for reaching reliable and reproducible audit conclusions in a systematic audit process. It states that audit evidence should be verifiable and should be based on samples of the information available, since an audit runs for a specified duration with finite resources, and that appropriate sampling should be applied because this bears directly on the confidence that can be placed in the conclusions.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-conducting-interviews', 'Conducting interviews',
   'ISO 19011:2026 Annex A.17 treats interviews as an important means of collecting information, carried out in a manner adapted to the situation and the individual, face-to-face or by other means. It asks that interviews be held with individuals from appropriate levels and functions performing activities within the audit scope, normally during working hours and where practical at the normal workplace, that the interviewee be put at ease, and that the reason for the interview and any note taking be explained.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-interview-selection-of-persons', 'Choosing whom to interview',
   'ISO 19011:2026 Annex A.17 a) asks that interviews be held with individuals from appropriate levels and functions performing the activities or tasks within the audit scope. For an AI management system this means the people who actually prepare data, evaluate models or operate the system, not only the manager who can describe the intended process. Interviewing only upward produces a description of the design rather than evidence of the practice.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-interview-confirmation', 'Confirming what was recorded',
   'ISO 19011:2026 Annex A.17 asks that the reason for the interview and any note taking be explained, and that the results be summarised and reviewed with the interviewee. Confirming the record at the time is what allows a statement of fact to be relied on later, and it protects the interviewee from a finding built on something they did not mean.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-leading-question-risk', 'Question type shapes the evidence',
   'ISO 19011:2026 Annex A.17 f) asks that the type of question be carefully selected, naming open, closed, leading questions and appreciative inquiry, and A.17 g) notes the limited feasibility of non-verbal communication in virtual settings, directing attention instead to the type of question used to find objective evidence. A leading question produces agreement rather than information, and agreement is not evidence.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-remote-evidence-sufficiency', 'Sufficiency of remotely obtained evidence',
   'ISO 19011:2026 Annex A.16 records that an audit using remote methods uses technology during the audit process for observing, interviewing and verifying objective evidence, and that remote methods can introduce additional risks and opportunities. The verification test in Annex A.5 does not change with the method: the auditor still asks whether the information is complete, correct, consistent and current, and whether its integrity can be assessed.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-screen-share-verification', 'What a demonstration shows',
   'A screen share shows what the person operating it chose to display, at the moment they displayed it. That can be genuine evidence of a control operating, and it can equally be a filtered view or a prepared environment. Annex A.5 asks that where information is provided in a manner other than expected, the integrity of the audit evidence be assessed; recording what was actually observed, and by whom it was navigated, is how the auditor keeps that assessment possible.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-remote-access-limits', 'Access and its limits',
   'ISO 19011:2026 clause 6.4.5 covers providing access to audit information, and Annex A.16 asks the auditee and audit team to ensure appropriate resources are available when remote methods are used, including agreed remote access protocols, devices and software. Where access is partial, the limit belongs in the audit record: an area the auditor could not reach is an area the audit did not cover, and the report should say so rather than leaving it implied.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-remote-vs-onsite-tradeoff', 'Choosing between remote and on-site',
   'Remote is not the lesser option and on-site is not automatically the rigorous one. Documentary evidence, registries and logs are examined equally well from anywhere; the operating environment, physical controls and the observable behaviour of a team may not be. ISO 19011:2026 clause 5.5.3 asks that the balance of methods be suitably balanced with consideration of associated risks and opportunities, which makes the choice a recorded judgement rather than a default.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-sources-of-information', 'Selecting sources of information',
   'ISO 19011:2026 Annex A.14 addresses selecting sources of information, which vary with the scope and complexity of the audit and can include interviews, observation, documented information, records, data summaries and reports from other sources. The choice follows from the question being asked: a summary answers a different question from the record it summarises.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-aims-evidence-types', 'Evidence types specific to an AI management system',
   'An AIMS audit draws on sources a general management-system auditor may not have sampled: documentation of data resources, tooling and computing resources, records of human resources and their competences, AI system technical documentation, event logs, impact assessment outputs and records of system operation and monitoring. ISO/IEC 42001:2023 Annex A control families A.4, A.6 and A.7 are where these originate.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-data-and-tooling-records', 'Data, tooling and resource documentation',
   'ISO/IEC 42001:2023 Annex A.4 covers resources for AI systems, with controls addressing resource documentation and, as part of resource identification, information about data resources, tooling resources, system and computing resources, and human resources and their competences. Annex A.7 covers data for AI systems, including acquisition, quality, provenance and preparation. Where the organization has selected these controls, the documentation they call for is what the auditor samples.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-opening-meeting', 'The opening meeting',
   'ISO 19011:2026 clause 6.4.3 covers the opening meeting, whose purpose is to confirm the agreement of all parties to the audit plan, introduce the audit team and their roles, and ensure that the planned activities can be performed. Its degree of formality varies with the type of audit; for a routine internal audit it can be simply communicating that the audit is being conducted and explaining its nature.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-closing-meeting', 'The closing meeting',
   'ISO 19011:2026 clause 6.4.10 covers the closing meeting, at which the audit findings and conclusions are presented so that they are understood and acknowledged. It is where diverging opinions between the audit team and the auditee are discussed and, where possible, resolved, and where any unresolved difference is recorded rather than smoothed over.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-guides-and-observers', 'Guides and observers',
   'ISO 19011:2026 clause 6.4.2 covers assigning the roles and responsibilities of guides and observers. A guide accompanies the audit team, arranges access and interviews and provides clarification; an observer attends without auditing. Neither acts as an auditor, and the presence of either should not influence or interfere with the conduct of the audit.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-clause-4-1-context', 'Clause 4.1 context of the organization',
   'ISO/IEC 42001:2023 clause 4.1 requires the organization to determine external and internal issues relevant to its purpose that affect its ability to achieve the intended results of its AI management system, to consider the intended purpose of the AI systems it develops, provides or uses, and to determine its roles with respect to those systems. It also requires the organization to determine whether climate change is a relevant issue. All four are stated as shall.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-role-determination-evidence', 'Evidence of the role determination',
   'The role determination under clause 4.1 is auditable because it produces an output: the AI systems named, a role assigned to each, and the reasoning behind the assignment. The auditor tests whether that output exists and whether it covers the systems actually in use, rather than whether the organization can describe its roles when asked.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-role-assertion-vs-determination', 'Determination and assertion',
   'A determination applies the developer, provider and user categories to named systems and records why each applies. An assertion says the organization uses AI. The first can be tested against the estate and against clause 4.3 scope; the second cannot be tested at all. Where only the assertion exists, the requirement in clause 4.1 to determine roles has not been met even though the topic has been addressed.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-intended-purpose-consideration', 'Intended purpose of the AI systems',
   'ISO/IEC 42001:2023 clause 4.1 requires the organization to consider the intended purpose of the AI systems it develops, provides or uses. Intended purpose is what shapes both the role determination and, later, the impact assessment under 6.1.4, which addresses deployment, intended use and foreseeable misuse. A system whose intended purpose was never recorded leaves both downstream determinations without a basis.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-external-internal-issues', 'External and internal issues',
   'Clause 4.1 requires determination of external and internal issues relevant to the organization''s purpose and affecting its ability to achieve the intended results of the AI management system. For an AI management system these commonly include applicable regulation, the expectations of affected individuals, the maturity of the technology in use, and dependence on external model or data providers.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-clause-4-3-scope', 'Clause 4.3 scope of the AI management system',
   'ISO/IEC 42001:2023 clause 4.3 requires the organization to determine the boundaries and applicability of the AI management system to establish its scope, considering the external and internal issues from 4.1 and the requirements of interested parties from 4.2. The scope is documented information.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-scope-boundaries-applicability', 'Boundaries and applicability',
   'Boundaries say where the management system stops; applicability says what within those boundaries it governs. For an AI management system the two are separable: an organization can place a business unit inside the boundary while excluding a category of AI system within it. The auditor tests both, since a scope that names only organizational units has not addressed applicability to the AI systems themselves.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-interested-party-requirements', 'Interested parties and their requirements',
   'ISO/IEC 42001:2023 clause 4.2 requires the organization to determine the interested parties relevant to the AI management system, their relevant requirements, and which of those requirements will be addressed through the management system. The third element is the one most often missing: identifying a requirement without recording whether the AIMS addresses it leaves the determination incomplete.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-scope-exclusion-justification', 'Testing an exclusion',
   'Clause 4.3 does not require the organization to justify exclusions in the way clause 6.1.3 f) requires justification for controls, but an exclusion still has to be consistent with the issues, interested-party requirements and roles that clauses 4.1 and 4.2 produced. An AI system the organization develops, sitting outside a scope that claims to cover development, is an inconsistency the auditor can evidence from the organization''s own determinations.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-clause-5-leadership', 'Clause 5.1 leadership and commitment',
   'ISO/IEC 42001:2023 clause 5.1 requires top management to demonstrate leadership and commitment by ensuring the AI policy and AI objectives are established and compatible with the strategic direction, ensuring integration of AIMS requirements into business processes, ensuring resources are available, communicating the importance of effective AI management and of conforming to AIMS requirements, ensuring the system achieves its intended results, directing and supporting persons, and promoting continual improvement. Each is auditable through artifacts rather than through attitude.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-ai-policy-requirements', 'Clause 5.2 AI policy',
   'ISO/IEC 42001:2023 clause 5.2 requires top management to establish an AI policy that is appropriate to the purpose of the organization, provides a framework for setting AI objectives, and includes commitments to meet applicable requirements and to continual improvement. The policy shall be available as documented information, refer as relevant to other organizational policies, be communicated within the organization, and be available to interested parties as appropriate. This is a clause requirement and applies whether or not control A.2.2 is selected.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-policy-review-a-2-4', 'Reviewing the AI policy',
   'Table A.1 control A.2.4 states that the AI policy shall be reviewed at planned intervals or additionally as needed to ensure its continuing suitability, adequacy and effectiveness. Like every Table A.1 control it applies where the organization has selected it under clause 6.1.3 and declared it in the statement of applicability. Clause 5.2 requires the policy to exist; A.2.4 is where periodic review of it comes from.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-roles-responsibilities-authorities', 'Clause 5.3 roles, responsibilities and authorities',
   'ISO/IEC 42001:2023 clause 5.3 requires top management to ensure responsibilities and authorities for relevant roles are assigned and communicated, and specifically to assign responsibility and authority for ensuring the AIMS conforms to the requirements of the standard and for reporting on its performance to top management. A note points to control A.3.2 for defining and allocating AI roles and responsibilities.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-clause-6-1-2-risk-assessment', 'Clause 6.1.2 AI risk assessment',
   'ISO/IEC 42001:2023 clause 6.1.2 requires the organization to define and establish an AI risk assessment process that is informed by and aligned with the AI policy and AI objectives, is designed so that repeated assessments produce consistent, valid and comparable results, identifies risks that aid or prevent achieving the AI objectives, analyses those risks, and evaluates them. The requirement is on the process and its properties.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-risk-criteria', 'Risk criteria',
   'Clause 6.1.2 requires the risk assessment process to identify, analyse and evaluate AI risks, which presupposes criteria against which risks are evaluated. The auditor tests the process against the criteria the organization itself established, since clause 9.2.1 makes the organization''s own requirements for its AIMS part of the audit criteria alongside the standard.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-repeatable-comparable-results', 'Consistent, valid and comparable results',
   'ISO/IEC 42001:2023 clause 6.1.2 b) requires the process to be designed such that repeated AI risk assessments can produce consistent, valid and comparable results. This is testable: two assessments of similar systems, performed by different people, that reach materially different conclusions on the same facts indicate a process that does not meet 6.1.2 b), and the evidence for the finding is the organization''s own assessment records.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-no-risk-register-requirement', 'No clause requires a risk register',
   'The phrase risk register does not appear anywhere in ISO/IEC 42001:2023. Clause 6.1.2 requires a documented AI risk assessment process; clause 6.1.3 requires a documented risk treatment process and a statement of applicability; clause 6.1.4 requires the result of the impact assessment to be documented. An organization may keep a register and many do, but its absence is not a nonconformity and an auditor who raises one has cited a requirement the standard does not contain.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-clause-6-1-3-risk-treatment', 'Clause 6.1.3 AI risk treatment',
   'ISO/IEC 42001:2023 clause 6.1.3 requires the organization to define an AI risk treatment process that selects appropriate treatment options; determines all controls necessary to implement them and compares those controls with Annex A to verify that no necessary control has been omitted; considers the Annex A controls relevant to the chosen options; identifies any additional controls needed beyond Annex A; considers the guidance in Annex B for implementation; and produces a statement of applicability containing the necessary controls with justification for inclusion and exclusion.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-statement-of-applicability', 'The statement of applicability',
   'ISO/IEC 42001:2023 clause 3.26 defines the statement of applicability as documentation of all necessary controls and justification for inclusion or exclusion of controls. Clause 6.1.3 f) is the requirement that produces it. It is the document that converts the reference controls of Annex A into this organization''s obligations, which is why a Table A.1 control becomes auditable only once it appears there as included.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-control-comparison-annex-a', 'Comparing determined controls with Annex A',
   'Clause 6.1.3 b) requires the organization to determine all controls necessary to implement the chosen treatment options and to compare them with those in Annex A to verify that no necessary control has been omitted. The direction matters: controls are determined from the risks first and Annex A is then used as a completeness check. An organization that started from Table A.1 and worked backwards has performed a different exercise, and the audit evidence for the comparison is what shows which happened.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-additional-controls-beyond-annex-a', 'Controls beyond Annex A',
   'Clause 6.1.3 d) requires the organization to identify whether additional controls are necessary beyond those in Annex A, and Annex A.1 records that the organization can design and implement its own controls. Annex A is a reference set and not a ceiling. A statement of applicability containing only Table A.1 rows is not automatically deficient, but it does invite the question of whether step d) was performed.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-clause-6-1-4-impact-assessment', 'Clause 6.1.4 AI system impact assessment',
   'ISO/IEC 42001:2023 clause 6.1.4 requires the organization to define a process for assessing the potential consequences for individuals or groups of individuals, or both, and societies, that can result from the development, provision or use of AI systems. The assessment shall determine the potential consequences of the system''s deployment, intended use and foreseeable misuse; shall take into account the specific technical and societal context and applicable jurisdictions; and its result shall be documented. The organization shall consider the results in the risk assessment referred to in 6.1.2.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-impact-vs-risk-assessment', 'Impact assessment and risk assessment are distinct',
   'The two processes answer different questions. Clause 6.1.2 assesses risks to the achievement of the organization''s AI objectives. Clause 6.1.4 assesses potential consequences for individuals, groups of individuals and societies. They are separately required, separately defined, and directionally linked: 6.1.4 requires its results to be considered in the risk assessment. An organization that has run one process and labelled it both has not met one of the two requirements.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-consequences-for-individuals-societies', 'Consequences for individuals and societies',
   'Clause 6.1.4 directs the impact assessment outward, to individuals, groups of individuals and societies, rather than inward to the organization. This is the substantive difference from a conventional management-system risk assessment, where consequences are usually scoped to the organization''s own objectives. Note that clause 6.1.2 d) 1) does ask the risk analysis to assess potential consequences to the organization, individuals and societies, and its NOTE records that an impact assessment can be used for that purpose.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-impact-results-into-risk-assessment', 'Feeding impact results into the risk assessment',
   'Clause 6.1.4 states that the organization shall consider the results of the AI system impact assessment in the risk assessment. The requirement is directional and it is a shall. Evidence that satisfies it shows the impact findings appearing in the risk assessment record; an impact assessment filed separately and never referenced leaves this requirement unevidenced even where both documents exist and are individually sound.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-clause-8-4-operational-impact-assessment', 'Clause 8.4 performing the impact assessment',
   'ISO/IEC 42001:2023 separates defining the process from performing it. Clause 6.1.4 requires the process to be defined; clause 8.4 requires the organization to perform AI system impact assessments at planned times and when significant changes occur, and to retain documented information of the results. The same split applies to risk: 6.1.2 and 6.1.3 define, 8.2 and 8.3 perform.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-annex-a-5-impact-controls', 'Annex A.5 controls for assessing impacts',
   'Table A.1 control family A.5, assessing impacts of AI systems, carries the reference controls supporting clauses 6.1.4 and 8.4, including A.5.2 on an AI system impact assessment process and A.5.5 on assessing societal impacts of AI systems. Where the organization has selected these controls, they are declared in the statement of applicability and their implementation is auditable; the clause requirements apply regardless of selection.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-clause-7-5-documented-information', 'Clause 7.5 documented information',
   'ISO/IEC 42001:2023 clause 7.5.1 requires the AI management system to include the documented information required by the standard and that determined by the organization as necessary for the system''s effectiveness. Clause 7.5.2 covers creating and updating it, and 7.5.3 covers its control. A note in 7.5.1 records that the extent can differ between organizations according to size, complexity of processes and competence of persons, so volume is not itself a measure of conformity.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-creating-updating-control', 'Creating, updating and controlling',
   'Clause 7.5.2 requires that when creating and updating documented information the organization ensure appropriate identification and description, format and media, and review and approval for suitability and adequacy. Clause 7.5.3 requires it to be available and suitable for use where needed, and adequately protected. Existence is not control: a current model card that nobody approved and that anyone can overwrite satisfies neither subclause.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-awareness-and-communication', 'Awareness and communication',
   'ISO/IEC 42001:2023 clause 7.3 requires persons doing work under the organization''s control to be aware of the AI policy, their contribution to the effectiveness of the AIMS, and the implications of not conforming to its requirements. Clause 7.4 requires the organization to determine the internal and external communications relevant to the AIMS, including what, when, with whom and how.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-documented-information-vs-record', 'Documented information and evidence',
   'ISO/IEC 42001:2023 uses documented information for both what the organization maintains, such as a policy or a process definition, and what it retains as evidence, such as the result of an impact assessment under 6.1.4 or the audit results under 9.2.2. When testing a clause the auditor reads which of the two it asks for: a requirement to define a process is met by the process definition, and a requirement that documented information be available as evidence is met by the record of it having run.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-clause-8-1-operational-control', 'Clause 8.1 operational planning and control',
   'ISO/IEC 42001:2023 clause 8.1 requires the organization to plan, implement and control the processes needed to meet requirements and to implement the actions determined in Clause 6, by establishing criteria for the processes and implementing control in accordance with those criteria. It further requires the organization to implement the controls determined according to 6.1.3 that relate to the operation of the AIMS, and requires that the effectiveness of those controls be monitored and corrective actions considered where intended results are not achieved.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-outsourced-processes', 'Externally provided processes and products',
   'Clause 8.1 requires the organization to control planned changes and review the consequences of unintended changes, and to ensure that externally provided processes, products or services relevant to the AI management system are controlled. For an AI management system this reaches third-party models, datasets and hosted services, which is where Table A.1 family A.10 on third-party and customer relationships becomes relevant if selected.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-planned-changes-control', 'Planning of changes',
   'ISO/IEC 42001:2023 clause 6.3 requires that when the organization determines the need for changes to the AI management system, the changes shall be carried out in a planned manner. Clause 8.1 adds control of planned changes and review of the consequences of unintended ones. A change to an AI system''s purpose, data or deployment context is where role determination and impact assessment can both fall out of date.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-clause-8-2-8-3-operational-risk', 'Clauses 8.2 and 8.3 performing risk work',
   'Clause 8.2 requires the organization to perform AI risk assessments at planned intervals or when significant changes are proposed or occur, and to retain documented information of the results. Clause 8.3 requires it to implement the AI risk treatment plan and retain documented information of the results. Where 6.1.2 and 6.1.3 require the processes to be defined, 8.2 and 8.3 require them to be run and the results kept.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-annex-a-normative-shall', 'Annex A is normative and states controls as shall',
   'Annex A of ISO/IEC 42001:2023 is designated normative and carries Table A.1, whose 38 reference controls are each stated with shall, for example that the organization shall document a policy for the development or use of AI systems. The modal is real, and it operates on the controls the organization has determined to be necessary and declared in its statement of applicability.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-annex-b-normative-but-should', 'Annex B is normative and written as should',
   'Annex B of ISO/IEC 42001:2023 is also designated normative, yet it is written almost entirely in should, and it restates each Table A.1 control under a Control heading in the should form. The same control therefore appears twice in one document with two different modals. The Annex A wording is the control; the Annex B wording introduces the implementation guidance that follows it.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-annex-b-binds-via-6-1-3-e', 'How Annex B binds',
   'Annex B is normative because clause 6.1.3 e) requires the organization to consider the guidance in Annex B for the implementation of the controls it has determined. What binds is the act of considering, not the content of any particular sentence. Clause B.1 makes the limit explicit: organizations do not have to document or justify inclusion or exclusion of implementation guidance in the statement of applicability, and the guidance is not always suitable or sufficient in all situations.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-annex-c-d-informative', 'Annexes C and D are informative',
   'Annex C of ISO/IEC 42001:2023, on potential AI-related organizational objectives and risk sources, and Annex D, on use of the AI management system across domains or sectors, are both designated informative. They inform and they impose nothing, and no finding can rest on them.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-modal-shall-should-note', 'Reading the modal',
   'In ISO/IEC 42001:2023 a shall is a requirement, a should is guidance and a note is neither. The distinction is structural rather than stylistic: clauses 4 to 10 contain 81 instances of shall and no should at all, while Annex B is almost entirely should. An auditor who preserves the modal in their own writing can be challenged on judgement; one who converts a should into a requirement can be challenged on the text.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-soa-inclusion-exclusion-justification', 'Justifying inclusion and exclusion',
   'Clause 6.1.3 f) requires the statement of applicability to contain the necessary controls and to provide justification for inclusions and exclusions. Both directions need a reason. A statement of applicability that lists included controls without justification, or that marks exclusions with a bare not applicable, has not met the clause even though every row is present.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-controls-not-all-required', 'Not every Annex A control applies',
   'Annex A.1 of ISO/IEC 42001:2023 states that not all the control objectives and controls listed in Table A.1 are required to be used, and that the organization can design and implement its own controls. A Table A.1 shall therefore operates conditionally: it applies to the organization that has determined the control necessary and declared it. Writing that ISO/IEC 42001 requires an AI policy control misstates this; writing that where A.2.2 is selected the organization shall document an AI policy does not.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-control-objectives-a-2-to-a-10', 'The Annex A control objectives',
   'Table A.1 organises its controls under nine families, each with a stated objective: A.2 policies related to AI, A.3 internal organization, A.4 resources for AI systems, A.5 assessing impacts of AI systems, A.6 AI system life cycle, A.7 data for AI systems, A.8 information for interested parties of AI systems, A.9 use of AI systems, and A.10 third-party and customer relationships. The objective states what the family is for, which is what an exclusion has to be justified against.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-soa-vs-implementation-evidence', 'The statement of applicability is not the evidence',
   'A statement of applicability records what the organization decided. Implementation evidence shows what it did. Clause 8.1 requires the organization to implement the controls determined according to 6.1.3, so a control declared as included and not implemented is a nonconformity against clause 8.1 rather than against Table A.1. Reading only the statement of applicability tests the decision and not the operation.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-climate-change-4-1', 'Climate change in clause 4.1',
   'ISO/IEC 42001:2023 clause 4.1 states that the organization shall determine whether climate change is a relevant issue. The requirement is to make and record the determination; the standard does not prescribe the answer, and an organization that determines climate change is not a relevant issue and records why has met the requirement.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-climate-note-4-2', 'The climate note in clause 4.2',
   'Clause 4.2 carries a note recording that relevant interested parties can have requirements related to climate change. It is a note, which makes it neither a requirement nor guidance in the sense a should carries, and no finding can be raised on it. It signals where the topic can surface when interested-party requirements are determined.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-climate-native-not-amendment', 'Climate wording is in the first edition',
   'The climate change wording is present in the published first edition of ISO/IEC 42001:2023. There is no amendment to the standard, and a citation to ISO/IEC 42001:2023/Amd 1 refers to a document that does not exist. This differs from ISO/IEC 27001:2022, which acquired the same two additions through Amendment 1:2024, and it is a distinction an auditor working across both standards should keep straight.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-control-families-a-2-to-a-10', 'Testing a control across the families',
   'Testing whether a declared control is implemented as declared is one competence that applies across all nine Annex A families. The auditor takes a control the organization included in its statement of applicability, identifies what evidence its implementation would produce, and examines that evidence. What changes between families is the evidence type, not the method.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-declared-vs-implemented', 'Declared and implemented',
   'The statement of applicability is a claim; implementation evidence tests it. Three outcomes are possible: the control is implemented as declared, it is implemented differently from the declaration, or it is not implemented. The second is the one most often missed, because the control exists and the evidence exists but they describe different arrangements, and only reading the declaration against the evidence reveals it.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-a-4-resource-documentation', 'Annex A.4 resources for AI systems',
   'Table A.1 family A.4 addresses resources for AI systems. Its controls cover documenting relevant resources for AI system life cycle activities and, as part of resource identification, documenting information about data resources, tooling resources, system and computing resources, and human resources and their competences. These are documentation controls, so where selected the evidence is the documentation itself.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-a-6-life-cycle-controls', 'Annex A.6 AI system life cycle',
   'Table A.1 family A.6 addresses the AI system life cycle, including management guidance for AI system development and controls across life cycle stages. Its controls reach objectives for responsible development, life cycle processes, verification and validation, deployment, operation and monitoring, technical documentation and event logging. Some carry an internal qualifier: A.6.2.6 asks that the organization define and document the necessary elements for ongoing operation, and states that at a minimum this should include system and performance monitoring, repairs, updates and support.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-a-7-data-controls', 'Annex A.7 data for AI systems',
   'Table A.1 family A.7 addresses data for AI systems, with controls covering acquisition of data, quality of data for AI systems, data provenance and data preparation. These call for documentation that a conventional management-system audit has no counterpart to, and they are among the families most likely to go unsampled if the auditor works from familiar territory.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-clause-7-2-competence', 'Clause 7.2 competence',
   'ISO/IEC 42001:2023 clause 7.2 requires the organization to determine the necessary competence of persons doing work under its control that affects its AI performance, to ensure those persons are competent on the basis of appropriate education, training or experience, and where applicable to take action to acquire the necessary competence and evaluate the effectiveness of those actions. Appropriate documented information shall be available as evidence of competence.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-a-4-6-human-resources', 'Control A.4.6 human resources',
   'Table A.1 control A.4.6 states that, as part of resource identification, the organization shall document information about the human resources and their competences used across the AI system life cycle, covering development, deployment, operation, change management, maintenance and transfer. Where selected, it produces a record that can be read against the competence determined under clause 7.2.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-competence-evidence-vs-headcount', 'Evidence of competence',
   'A job title is not evidence of competence and a headcount is not evidence that competence was determined. Clause 7.2 asks first what competence the work requires and then whether the people doing it hold it, on the basis of education, training or experience, with documented information available as evidence. The common gap is an AIMS that states a competence standard which the personnel records do not evidence.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-organizational-vs-auditor-competence', 'Two different competence questions',
   'Clause 7.2 concerns the competence of the organization''s own people doing work that affects AI performance. ISO 19011:2026 clause 7 concerns the competence of the auditors. They are separate questions with separate sources, and an internal auditor can hold one while raising a finding about the other.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-recording-conformities', 'Recording a conformity',
   'ISO 19011:2026 Annex A.18.2 asks that a record of conformity consider a description of or reference to the audit criteria against which conformity is demonstrated, the audit evidence supporting conformity and effectiveness where applicable, and a declaration of conformity where applicable. Clause 6.4.8 adds that where the audit plan specifies it, findings of conformity and of good practice should be recorded with their supporting evidence.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-recording-nonconformities', 'Recording a nonconformity',
   'ISO 19011:2026 Annex A.18.3 asks that a record of nonconformity consider a description of or reference to the audit criteria, the audit evidence, a declaration of nonconformity including a description explaining why the criteria are not fulfilled, any related findings, and the grade where grading is used. The three load-bearing parts are the criterion, the evidence, and the explanation of why the one does not meet the other.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-opportunity-for-improvement', 'Opportunities for improvement',
   'ISO 19011:2026 clause 3.11 Note 2 records that audit findings can lead to the identification of risks, opportunities for improvement, or the recording of good practices, and clause 6.4.8 provides for recording opportunities for improvement and any recommendations where the audit plan specifies. An opportunity for improvement is not a weak nonconformity: it is what an auditor records when the criteria are met and something could still be better.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-classification-scheme-is-an-organizational-choice', 'Grading nonconformities is an organizational choice',
   'ISO/IEC 42001 uses only the term nonconformity and defines no severity scheme. A major and minor distinction comes from third-party certification practice under ISO/IEC 17021-1. ISO 19011:2026 clause 6.4.8 records that nonconformities can be graded depending on the context of the organization and its risks, that grading can be quantitative or qualitative, and that where grading is used the criteria should be defined and communicated by the auditing organization. Unlike ISO/IEC 27001, which relies on ISO/IEC 27000 for the term, ISO/IEC 42001 defines nonconformity itself at clause 3.16 as non-fulfilment of a requirement, alongside conformity at 3.15 and corrective action at 3.17.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-finding-structure', 'The structure of a finding',
   'A nonconformity statement names the requirement, states the evidence, and asserts the gap between them. ISO 19011:2026 clause 3.11 defines an audit finding as the result of evaluating collected audit evidence against the audit criteria, which is why a statement missing either the criterion or the evidence is not yet a finding.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-evidence-requirement-link', 'Linking evidence to requirement',
   'The link is what a finding is. Evidence without a requirement is an observation; a requirement without evidence is an assertion. Annex A.18.3 c) asks for a declaration of nonconformity including a description explaining why the audit criteria are not fulfilled, which is the link stated explicitly rather than left for the reader to infer.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-finding-does-not-prescribe-remedy', 'A finding does not prescribe the remedy',
   'Deciding how to correct a nonconformity belongs to the auditee. ISO 19011:2026 clause 6.7 records that corrections and corrective actions are usually decided and undertaken by the auditee. An auditor who writes the fix into the finding has made the auditee''s decision for them and has also made the finding harder to close, because it can now be satisfied only one way.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-finding-does-not-attribute-intent', 'A finding does not attribute intent',
   'A finding records what the evidence showed against the criterion. Whether anyone intended, concealed or neglected anything is not something audit evidence establishes, and asserting it converts a factual statement into an allegation the auditor cannot support. ISO 19011:2026 clause 4.3 asks that reporting be truthful, accurate, objective, timely, clear and complete, and attribution of motive fails the objectivity element.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-multiple-criteria-findings', 'Findings touching more than one criterion',
   'ISO 19011:2026 Annex A.18.4 addresses dealing with audit findings related to multiple criteria, where a single body of evidence bears on requirements from more than one source. In an AIMS audit this arises where the same evidence engages an ISO/IEC 42001 clause, an Annex A control the organization declared, and the organization''s own AIMS requirement.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-combining-vs-separating-findings', 'One finding or several',
   'The choice is between recording one finding that references the several criteria it engages, and recording separate findings each against its own criterion. Annex A.18.4 permits the auditor to combine references into a single finding. What decides it is what the reader has to do with it: separate findings that will be corrected by one action create work without adding information, and a combined finding that hides distinct failures conceals them.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-criteria-cross-reference', 'Naming every criterion engaged',
   'Where a finding is combined, each criterion it engages is still named. Annex A.18.3 a) asks for a description of or reference to the audit criteria, and the plural matters: a finding that cites the clause but not the declared control it also breaches leaves part of its own basis unstated and is harder to defend if challenged.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-finding-against-should-text', 'A should cannot carry a nonconformity',
   'A nonconformity is the non-fulfilment of a requirement, as ISO/IEC 42001:2023 clause 3.16 defines it. A should expresses guidance rather than a requirement, so text in the should form cannot be the criterion a nonconformity rests on. The auditor who finds the substance sound but the criterion in the should form records an observation or an opportunity for improvement instead.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-finding-against-annex-b', 'Findings and Annex B',
   'Annex B of ISO/IEC 42001:2023 is normative but its content is written as should, and clause B.1 states that organizations do not have to document or justify inclusion or exclusion of implementation guidance in the statement of applicability, and that the guidance is not always suitable or sufficient in all situations. A nonconformity therefore cannot be raised because an organization implemented a control differently from the Annex B guidance. What clause 6.1.3 e) requires is that the guidance be considered.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-finding-against-a-note', 'Findings and notes',
   'A note is neither a requirement nor guidance in the sense a should carries, and no finding rests on one. One drafting anomaly is worth knowing rather than turning into an exam point: Note 2 to entry under ISO/IEC 42001:2023 clause 3.26 contains a shall. Where the statement of applicability is at issue, clause 6.1.3 f) is the requirement text to cite.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-nonconformity-needs-a-shall', 'Every nonconformity traces to a requirement',
   'Before a finding is recorded the auditor identifies the requirement it rests on and confirms the requirement exists in the form claimed. ISO 19011 contains none, so nothing can be found non-conforming to it. Annex A controls apply where declared. Clauses 4 to 10 of ISO/IEC 42001:2023 are stated in shall throughout and apply in full. A finding that cannot name its requirement is withdrawn, not softened.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-audit-report-content', 'What the audit report contains',
   'ISO 19011:2026 clause 6.5.1 asks that the audit report provide a complete, accurate, concise and clear record of the audit, and that it include or refer to the audit objectives, scope, audit client, audit team and auditee participants, dates and locations, audit criteria, findings with related evidence, conclusions, a statement of the degree to which the criteria have been fulfilled, any unresolved diverging opinions, and a statement that audits are by nature a sampling exercise carrying a risk that the evidence examined is not representative.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-report-distribution', 'Distributing the report',
   'ISO 19011:2026 clause 6.5.2 covers distributing the audit report, which should be issued within an agreed period and to the recipients defined in the audit programme or plan. ISO/IEC 42001:2023 clause 9.2.2 c) separately requires that the results of audits be reported to relevant managers, which is the requirement a finding about distribution would rest on.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-fair-presentation-in-reporting', 'Fair presentation in the report',
   'ISO 19011:2026 clause 4.3 states that audit findings, conclusions and reports should reflect the auditing activities truthfully and accurately, that significant obstacles encountered and unresolved diverging opinions between the audit team and the auditee should be reported, and that communication should be truthful, accurate, objective, timely, clear and complete. Omitting an obstacle that weakened the audit is a failure of the principle even when every finding recorded is correct.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-confidentiality-in-reporting', 'Confidentiality against completeness',
   'ISO 19011:2026 clause 4.5 asks auditors to exercise discretion in the use and protection of information acquired during auditing, including proper handling of sensitive or confidential information. This can pull against the completeness that clause 4.3 asks for, particularly where evidence includes personal data or commercially sensitive model details. Nothing in the text ranks the two, and the usual resolution is to state the finding fully while holding the underlying evidence in the audit record rather than the distributed report.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-clause-10-2-corrective-action', 'Clause 10.2 nonconformity and corrective action',
   'ISO/IEC 42001:2023 clause 10.2 requires that when a nonconformity occurs the organization shall react to it, taking action to control and correct it and dealing with the consequences as applicable; evaluate the need for action to eliminate the causes so it does not recur or occur elsewhere, by reviewing the nonconformity, determining its causes and determining whether similar nonconformities exist or could occur; implement any action needed; review the effectiveness of any corrective action taken; and make changes to the AIMS if necessary. Corrective actions shall be appropriate to the effects of the nonconformities encountered.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-correction-vs-corrective-action', 'Correction and corrective action',
   'A correction addresses the instance; a corrective action addresses the cause so the instance does not recur or occur elsewhere. ISO/IEC 42001:2023 clause 10.2 a) covers the first and 10.2 b) the second, and they are separate obligations. Completing the missing documentation for one AI system is a correction; establishing why it was missing and whether other systems are affected is the corrective action.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-cause-analysis', 'Determining causes',
   'Clause 10.2 b) requires the organization to review the nonconformity, determine its causes, and determine whether similar nonconformities exist or can potentially occur. The third element is the one most often skipped: an organization that has fixed the instance and identified a cause but never asked where else the cause operates has not completed 10.2 b), and the evidence of that omission is in its own corrective action record.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-follow-up-verification', 'Verifying that action was effective',
   'ISO/IEC 42001:2023 clause 10.2 d) requires the organization to review the effectiveness of any corrective action taken. ISO 19011:2026 clause 6.7 adds that the completion and effectiveness of actions should be verified, and that this verification can be part of a subsequent audit. A finding closed on the strength of a commitment to act, rather than on evidence that action was taken and worked, has not been verified.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-clause-9-3-management-review', 'Clause 9.3 management review',
   'ISO/IEC 42001:2023 clause 9.3.1 requires top management to review the organization''s AI management system at planned intervals to ensure its continuing suitability, adequacy and effectiveness. Clause 9.3.2 lists the required inputs and 9.3.3 the required outputs. Documented information shall be available as evidence of the results of management reviews.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-audit-results-as-review-input', 'Audit results as a management review input',
   'ISO/IEC 42001:2023 clause 9.3.2 requires the management review to include, among its inputs, information on AI management system performance including trends in nonconformities and corrective actions, in monitoring and measurement results, and in audit results. Internal audit output is therefore not an end in itself: it is a named input to the review, and a management review record that does not reflect audit results leaves that element of 9.3.2 unevidenced.'),
  ('4818fc03-6da0-4266-9329-0e1ea2ea3fb4', 'aia-review-results-9-3-3', 'Results of the management review',
   'Clause 9.3.3 requires the results of the management review to include decisions related to continual improvement opportunities and any need for changes to the AI management system, and requires documented information to be available as evidence of those results. A review that records attendance and discussion but no decisions has not produced what 9.3.3 asks for.');

