commit;

-- ============================================================================
-- PROOF
-- ============================================================================

-- 1. Counts. Expect concepts 158, links 158, orphan concepts 0.
select
  (select count(*) from public.concepts where certification_id = '4818fc03-6da0-4266-9329-0e1ea2ea3fb4')          as concepts,
  (select count(*) from public.task_concepts tc join public.tasks t on t.id = tc.task_id
    where t.certification_id = '4818fc03-6da0-4266-9329-0e1ea2ea3fb4')                                            as links,
  (select count(*) from public.concepts c where c.certification_id = '4818fc03-6da0-4266-9329-0e1ea2ea3fb4'
    and not exists (select 1 from public.task_concepts tc where tc.concept_id = c.id)) as orphan_concepts;

-- 2. Concepts per task. Expect 40 rows, each 3 to 6, none zero.
select t.code, count(tc.concept_id) as concepts
from public.tasks t
left join public.task_concepts tc on tc.task_id = t.id
where t.certification_id = '4818fc03-6da0-4266-9329-0e1ea2ea3fb4'
group by t.code, t.order_index order by t.order_index;

-- 3. ATTRIBUTION PROOF, in the shape migration 198 used. No concept may claim a
--    guidance document requires or mandates anything. Expect ZERO rows.
select c.slug, left(c.description, 140) as description
from public.concepts c
where c.certification_id = '4818fc03-6da0-4266-9329-0e1ea2ea3fb4'
  and c.description ~* '(19011|17021|42006)[^.]{0,70}\m(requires|mandates)\M'
  and c.description !~* '\m(never|not|no)\M[^.]{0,60}(19011|17021|42006)'
order by c.slug;

-- 4. No concept describes Annex B as informative, and none asserts a Table A.1
--    control unconditionally. Expect ZERO rows.
select c.slug, left(c.description, 140) as description
from public.concepts c
where c.certification_id = '4818fc03-6da0-4266-9329-0e1ea2ea3fb4'
  and (c.description ~* 'Annex B[^.]{0,50}\minformative\M'
       or c.description ~* '42001[^.]{0,30}\mrequires\M[^.]{0,40}\mcontrol\M')
  -- Exclude the concepts that state the rule BY QUOTING THE ERROR. Three guards
  -- tonight matched the text warning against the pattern they check for; this is
  -- the same defect HANDOFF v6.7 records, and the guard is what gets fixed.
  and c.description !~* '(misstates|misdescribes|does not|cannot|never|is wrong|incorrect)'
order by c.slug;

-- 5. No concept asserts that any clause requires a risk register. Expect ONE row,
--    aia-no-risk-register-requirement, which says the opposite.
select c.slug, left(c.description, 120) as description
from public.concepts c
where c.certification_id = '4818fc03-6da0-4266-9329-0e1ea2ea3fb4' and c.description ~* 'risk register'
order by c.slug;

-- 6. Read the D4 concepts. They assert what ISO/IEC 42001 requires, and they are
--    what the item generator will treat as true.
select c.slug, c.name, c.description
from public.concepts c
join public.task_concepts tc on tc.concept_id = c.id
join public.tasks t on t.id = tc.task_id
where c.certification_id = '4818fc03-6da0-4266-9329-0e1ea2ea3fb4' and t.code like '4.%'
order by t.order_index, c.slug;
